/**
 * Turns the single-line SQL generated by TypeORM into something a person can
 * read: bound parameters are written into the text, quotes around plain
 * identifiers are removed, and each clause starts on its own line.
 *
 * FOR DISPLAY ONLY. The query that is executed keeps its bound parameters.
 */
export function formatSql(sql: string, parameters: unknown[]): string {
  const values = [...parameters];
  const inline = (value: unknown): string =>
    typeof value === 'number' ? String(value) : `'${String(value).replaceAll("'", "''")}'`;

  return sql
    .replace(/\s+/g, ' ')
    .replace(/\?/g, () => inline(values.shift()))
    .replace(/"([A-Za-z_][A-Za-z0-9_]*)"/g, '$1')
    .replace(/ (FROM|INNER JOIN|LEFT JOIN|WHERE|GROUP BY|ORDER BY) /g, '\n$1 ')
    .replace(/ (UNION ALL) /g, '\n$1\n')
    .replace(/ (AND) /g, '\n  $1 ')
    .replace(/\) (SELECT) /g, ')\n$1 ')
    .replace(/ AS \((SELECT) /g, ' AS (\n$1 ')
    .replace(/, (?=[A-Za-z_.()]+ AS )/g, ',\n       ')
    .trim();
}
